def dedupe(items):
    """Return items with duplicates removed, first occurrence order preserved.

    Items are not guaranteed to be hashable. Must handle large inputs.
    """
    seen = set()
    out = []
    for item in items:
        try:
            if item in seen:
                continue
            seen.add(item)
        except TypeError:
            # Unhashable item: fall back to a linear scan of the output.
            if item in out:
                continue
        out.append(item)
    return out
